use dep::poseidon::poseidon2::Poseidon2;

global TREE_DEPTH: u32 = 20;

// Domain separation tags for Poseidon2 hashing
global LEAF_DOMAIN: Field = 0x4c454146; // "LEAF" in hex (right-aligned)
global NULLIFIER_DOMAIN: Field = 0x4e554c4c; // "NULLIFIER" in hex (right-aligned to 4 bytes)

// ============================================================================
// VERSIONING CONVENTION
// ============================================================================
//
// This circuit version is BACKWARD COMPATIBLE v1. When changes are made:
//
// COMPATIBLE VERSION (same version tag, increment in contracts if needed):
// - Adding additional constraints that don't change the leaf hash formula
// - Changing non-committed public inputs
// - Optimizing existing constraints
// - Adding new optional checks that old leaves still satisfy
//
// INCOMPATIBLE VERSION (new version tag, requires migration):
// - Changing the hash_leaf function (structure or domain tags)
// - Changing committed field count/order (nullifier, secret, amount)
// - Changing tree depth (affects all proofs)
// - Changing any domain separation tag used in hash_leaf or hash_nullifier
//
// When creating a new version:
// 1. Increment the version number in contracts/pool/src/lib.rs (CURRENT_CIRCUIT_VERSION)
// 2. Register the new VK via verifier::set_vk_for_version (version, vk_bytes)
// 3. Keep old VK registered - old notes must remain provable
// 4. Frontend: check note.version and use corresponding circuit
// 5. Pool: verify proofs against the note's stored version via verifier::verify_proof_for_version
//

fn hash2(a: Field, b: Field) -> Field {
    Poseidon2::hash([a, b], 2)
}

/// Note commitment. Built as a chain of two-input Poseidon2 hashes rather than
/// a single wide hash so that the exact same value can be recomputed by the
/// two other implementations that must agree with this circuit bit for bit:
/// the frontend (which only ships the two-input `hasher` circuit) and the pool
/// contract (whose `poseidon2_hash2` helper is two-input). A wide `hash3`/
/// `hash4` here would silently disagree with both.
///
/// `amount` is part of the commitment: notes carry their own value, so the
/// pool no longer needs a fixed per-pool denomination and a spend can pay out
/// part of a note and re-shield the rest.
///
/// `asset` is bound in exactly the same way as `amount`: a note is tied to one
/// SEP-41 asset, so a single pool can hold notes for many assets without a
/// proof for one asset ever opening a note of another. The pool contract
/// recomputes this same asset field from the payout token's address and rejects
/// a withdrawal whose leaf commits to a different asset, which is what makes the
/// binding sound on-chain rather than a naming convention.
fn hash_leaf(nullifier: Field, secret: Field, amount: Field, asset: Field) -> Field {
    hash2(hash2(hash2(hash2(LEAF_DOMAIN, nullifier), secret), amount), asset)
}

fn hash_nullifier(nullifier: Field) -> Field {
    hash2(hash2(NULLIFIER_DOMAIN, nullifier), 0)
}

/// Range-constrains `v` to 64 bits and returns it as a `u64`.
///
/// A bare `v as u64` in Noir truncates without constraining, so comparing two
/// truncated values would let a prover pass `amount = p - 1` (which wraps to a
/// small u64) and mint value out of nothing. Asserting the round trip back to
/// `Field` is what actually pins `v < 2^64`, which in turn makes the
/// `withdraw + change = amount` arithmetic below safe from field wraparound.
fn constrain_u64(v: Field) -> u64 {
    let narrowed = v as u64;
    assert(narrowed as Field == v);
    narrowed
}

fn constrain_bit(bit: Field) {
    assert(bit * (1 - bit) == 0);
}

fn compute_root(leaf: Field, path_siblings: [Field; TREE_DEPTH], path_bits: [Field; TREE_DEPTH]) -> Field {
    let mut cur = leaf;
    for i in 0..TREE_DEPTH {
        let sib = path_siblings[i];
        let bit = path_bits[i];
        constrain_bit(bit);
        let left = bit == 0;
        if left {
            cur = hash2(cur, sib);
        } else {
            cur = hash2(sib, cur);
        }
    }
    cur
}

/// Spends one note of arbitrary value: pays `withdraw_amount` out to
/// `recipient`, `relayer_fee` to the relayer submitting the transaction, and
/// re-shields the remainder as a brand-new note that the pool contract inserts
/// as a fresh leaf.
///
/// A change note is produced on *every* spend, including a full withdrawal
/// where the remainder is zero. That is deliberate: the on-chain footprint of
/// "withdrew everything" and "withdrew part" is then identical (one nullifier
/// spent, one leaf inserted), so an observer cannot tell from the transaction
/// shape whether the user still holds shielded value.
pub fn main(
    root: pub Field,
    nullifier_hash: pub Field,
    recipient: pub Field,
    withdraw_amount: pub Field,
    relayer_fee: pub Field,
    change_commitment: pub Field,
    asset: pub Field,
    nullifier: Field,
    secret: Field,
    amount: Field,
    change_nullifier: Field,
    change_secret: Field,
    path_siblings: [Field; TREE_DEPTH],
    path_bits: [Field; TREE_DEPTH],
) {
    // Value conservation. All three outputs (payout, fee, change) are pinned
    // to 64 bits first so the arithmetic below cannot wrap around the field
    // modulus.
    let amount_u64 = constrain_u64(amount);
    let withdraw_u64 = constrain_u64(withdraw_amount);
    let fee_u64 = constrain_u64(relayer_fee);

    // The sum of all outputs must not exceed the note's value.
    let total_out = withdraw_u64 + fee_u64;
    assert(total_out <= amount_u64);

    let change = amount - withdraw_amount - relayer_fee;

    // The spent note exists in the tree and carries exactly `amount` of
    // `asset`. `asset` is a public input, so the pool contract can check it
    // matches the token it is about to pay out (see asset_id_from_address).
    let leaf = hash_leaf(nullifier, secret, amount, asset);

    let nf = hash_nullifier(nullifier);
    assert(nf == nullifier_hash);

    let computed_root = compute_root(leaf, path_siblings, path_bits);
    assert(computed_root == root);

    // The re-shielded remainder is a well-formed note the spender can later
    // open, worth exactly what was not paid out and denominated in the same
    // `asset` -- so change can never silently switch a note to a different
    // asset than the one that was spent.
    let expected_change = hash_leaf(change_nullifier, change_secret, change, asset);
    assert(expected_change == change_commitment);

    // `recipient` is a committed public input. The front-running protection is
    // enforced on-chain: the pool contract recomputes the recipient hash from
    // the actual payout address and rejects the withdrawal unless it equals
    // this value (see recipient_hash_from_address). This assert simply keeps
    // the public input from being optimized away by the compiler.
    assert(recipient == recipient);
}

